static struct net *rtnl_get_peer_net(const struct rtnl_link_ops *ops,
				     struct nlattr *tbp[],
				     struct nlattr *data[],
				     struct netlink_ext_ack *extack)
{
	struct nlattr *tb[IFLA_MAX + 1];
	int err;

	if (!data || !data[ops->peer_type])
		return rtnl_link_get_net_ifla(tbp);

	err = rtnl_nla_parse_ifinfomsg(tb, data[ops->peer_type], extack);
	if (err < 0)
		return ERR_PTR(err);

	if (ops->validate) {
		err = ops->validate(tb, NULL, extack);
		if (err < 0)
			return ERR_PTR(err);
	}

	return rtnl_link_get_net_ifla(tb);
}

static int __rtnl_newlink(struct sk_buff *skb, struct nlmsghdr *nlh,
			  const struct rtnl_link_ops *ops,
			  struct net *tgt_net, struct net *link_net,
			  struct net *peer_net,
			  struct rtnl_newlink_tbs *tbs,
			  struct nlattr **data,
			  struct netlink_ext_ack *extack)
{
	struct nlattr ** const tb = tbs->tb;
	struct net *net = sock_net(skb->sk);
	struct net *device_net;
	struct net_device *dev;
	struct ifinfomsg *ifm;
	bool link_specified;

	/* When creating, lookup for existing device in target net namespace */
	device_net = (nlh->nlmsg_flags & NLM_F_CREATE) &&
		     (nlh->nlmsg_flags & NLM_F_EXCL) ?
		     tgt_net : net;

	ifm = nlmsg_data(nlh);
	if (ifm->ifi_index > 0) {
		link_specified = true;
		dev = __dev_get_by_index(device_net, ifm->ifi_index);
	} else if (ifm->ifi_index < 0) {
		NL_SET_ERR_MSG(extack, "ifindex can't be negative");
		return -EINVAL;
	} else if (tb[IFLA_IFNAME] || tb[IFLA_ALT_IFNAME]) {
		link_specified = true;
		dev = rtnl_dev_get(device_net, tb);
	} else {
		link_specified = false;
		dev = NULL;
	}

	if (dev)
		return rtnl_changelink(skb, nlh, ops, dev, tgt_net, tbs, data, extack);

	if (!(nlh->nlmsg_flags & NLM_F_CREATE)) {
		/* No dev found and NLM_F_CREATE not set. Requested dev does not exist,
		 * or it's for a group
		*/
		if (link_specified || !tb[IFLA_GROUP])
			return -ENODEV;

		return rtnl_group_changelink(skb, net, tgt_net,
					     nla_get_u32(tb[IFLA_GROUP]),
					     ifm, extack, tb);
	}

	if (tb[IFLA_MAP] || tb[IFLA_PROTINFO])
		return -EOPNOTSUPP;

	if (!ops) {
		NL_SET_ERR_MSG(extack, "Unknown device type");
		return -EOPNOTSUPP;
	}

	return rtnl_newlink_create(skb, ifm, ops, tgt_net, link_net, peer_net, nlh,
				   tb, data, extack);
}

